TLM.f("Tempora/Pent02-3",{"officium":"Feria Quarta infra Octavam Corporis Christi","rule":["ex Tempora/Pent01-4;","Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;","Prefatio=Communis"],"ruleInherited":["ex Tempora/Pent01-4","Gloria","Credo","Prefatio=Nat","Prefatio1960=Trinitate","Gloria","Credo","Prefatio=Communis","Sequentia","Gloria","Credo","Prefatio=Trinitate"],"fallback":"Tempora/Pent02-0r","from":{"Introitus":"Tempora/Pent02-0r","Oratio":"Tempora/Pent02-0r","Lectio":"Tempora/Pent02-0r","Graduale":"Tempora/Pent02-0r","Evangelium":"Tempora/Pent02-0r","Offertorium":"Tempora/Pent02-0r","Secreta":"Tempora/Pent02-0r","Communio":"Tempora/Pent02-0r","Postcommunio":"Tempora/Pent02-0r","Commemoratio Oratio":"Tempora/Pent02-0r","Commemoratio Secreta":"Tempora/Pent02-0r","Commemoratio Postcommunio":"Tempora/Pent02-0r"},"sections":{"Introitus":[{"k":"ref","la":"Ps 17:19-20"},{"k":"text","la":"Factus est Dóminus protéctor meus, et edúxit me in latitúdinem: salvum me fecit, quóniam vóluit me."},{"k":"ref","la":"Ps 17:2-3"},{"k":"text","la":"Díligam te. Dómine, virtus mea: Dóminus firmaméntum meum et refúgium meum et liberátor meus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Factus est Dóminus protéctor meus, et edúxit me in latitúdinem: salvum me fecit, quóniam vóluit me."}],"Oratio":[{"k":"text","la":"Sancti nóminis tui, Dómine, timórem páriter et amórem fac nos habére perpétuum: quia numquam tua gubernatióne destítuis, quos in soliditáte tuæ dilectiónis instítuis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Joánnis Apóstoli"},{"k":"ref","la":"1 John 3:13-18"},{"k":"text","la":"Caríssimi: Nolíte mirári, si odit vos mundus. Nos scimus, quóniam transláti sumus de morte ad vitam, quóniam dilígimus fratres. Qui non díligit, manet in morte: omnis, qui odit fratrem suum, homicída est. Et scitis, quóniam omnis homicída non habet vitam ætérnam in semetípso manéntem. In hoc cognóvimus caritátem Dei, quóniam ille ánimam suam pro nobis pósuit: et nos debémus pro frátribus ánimas pónere. Qui habúerit substántiam hujus mundi, et víderit fratrem suum necessitátem habére, et cláuserit víscera sua ab eo: quómodo cáritas Dei manet in eo? Filíoli mei, non diligámus verbo neque lingua, sed ópere et veritáte."}],"Graduale":[{"k":"ref","la":"Ps 119:1-2"},{"k":"text","la":"Ad Dóminum, cum tribulárer, clamávi, et exaudívit me."},{"k":"text","la":"Dómine, libera ánimam meam a lábiis iníquis, et a lingua dolósa. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 7:2"},{"k":"text","la":"Dómine, Deus meus, in te sperávi: salvum me fac ex ómnibus persequéntibus me et líbera me. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 14:16-24"},{"k":"text","la":"In illo témpore: Dixit Jesus pharisǽis parábolam hanc: Homo quidam fecit cœnam magnam, et vocávit multos. Et misit servum suum hora cœnæ dícere invitátis, ut venírent, quia jam paráta sunt ómnia. Et cœpérunt simul omnes excusáre. Primus dixit ei: Villam emi, et necésse hábeo exíre et vidére illam: rogo te, habe me excusátum. Et alter dixit: Juga boum emi quinque et eo probáre illa: rogo te, habe me excusátum. Et álius dixit: Uxórem duxi, et ídeo non possum veníre. Et revérsus servus nuntiávit hæc dómino suo. Tunc irátus paterfamílias, dixit servo suo: Exi cito in pláteas et vicos civitátis: et páuperes ac débiles et cæcos et claudos íntroduc huc. Et ait servus: Dómine, factum est, ut imperásti, et adhuc locus est. Et ait dóminus servo: Exi in vias et sepes: et compélle intrare, ut impleátur domus mea. Dico autem vobis, quod nemo virórum illórum, qui vocáti sunt, gustábit cœnam meam."}],"Offertorium":[{"k":"ref","la":"Ps 6:5"},{"k":"text","la":"Dómine, convértere, et éripe ánimam meam: salvum me fac propter misericórdiam tuam."}],"Secreta":[{"k":"text","la":"Oblátio nos, Dómine, tuo nómini dicánda puríficet: et de die in diem ad cœléstis vitæ tránsferat actiónem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 12:6"},{"k":"text","la":"Cantábo Dómino, qui bona tríbuit mihi: et psallam nómini Dómini altíssimi."}],"Postcommunio":[{"k":"text","la":"Sumptis munéribus sacris, quǽsumus, Dómine: ut cum frequentatióne mystérii, crescat nostræ salútis efféctus."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava SSmi. Corporis Christi"},{"k":"text","la":"Deus, qui nobis sub Sacraménto mirábili passiónis tuæ memóriam reliquísti: tríbue, quǽsumus, ita nos Córporis et Sánguinis tui sacra mystéria venerári; ut redemptiónis tuæ fructum in nobis júgiter sentiámus:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Ssmi Corporis Christi"},{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, unitátis et pacis propítius dona concéde: quæ sub oblátis munéribus mýstice designántur."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Ssmi Corporis Christi"},{"k":"text","la":"Fac nos, quǽsumus, Dómine, divinitátis tuæ sempitérna fruitióne repléri: quam pretiósi Córporis et Sánguinis tui temporális percéptio præfigúrat:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"ea91dc9f9b55cbba":{"t":"Ps 17, 19-20, Ps 17, 2-3\n(Ps 17, 19-20) Gospodin mi je postao obrana, on me je izveo na široko polje, spasio me jer me je ljubio. (Ps 17, 2-3) Ljubim te, Gospodine, jakosti moja! Gospodin je stijena moja, tvrđava moja, osloboditelj moj.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 17, 19-20) Gospodin mi je postao obrana, on me je izveo na široko polje, spasio me jer me je ljubio."},"48c2cbba12649407":{"t":"<i>Pomolimo se</i>.\nDaj, Gospodine, da tvoje sveto ime uvijek štujemo i ujedno ga trajno ljubimo, jer nikada ne prestaješ upravljati onima koje u svojoj ljubavi utvrđuješ.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"7564b4e60e745130":{"t":"1 Iv 3, 13-18\nČitanje Poslanice bl. Ivana apostola. Predragi, nemojte se čuditi, ako vas svijet mrzi. Mi znamo da smo iz smrti prešli u život, jer ljubimo braću. Tko ne ljubi, ostaje u smrti. Tko mrzi svojega brata, ubojica je. A znate da nijedan ubojica nema u sebi vječnoga života. Ljubav smo Božju upoznali po tome što je Bog dao svoj život za nas. Tako smo i mi dužni dati svoj život za braću. Ako netko ima dobara ovoga svijeta i vidi svoga brata u nevolji, pa mu zatvori svoje srce, kako da u njemu ostane Božja ljubav? Dječice moja, ne ljubimo riječju i jezikom, nego djelom i istinom."},"f246ad2e30e725c6":{"t":"Ps 119, 1-2\nU tjeskobi sam svojoj zazvao Gospodina i uslišio me. Gospodine, oslobodi me od zlobnih usta i himbena jezika.\n\nPs 7, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodine Bože moj, u tebe se uzdah! Spasi me od svih koji me progone i oslobodi me. <i>Aleluja</i>."},"d708dccb67da9f4c":{"t":"Lk 14, 16-24\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus farizejima ovu poredbu: Neki čovjek zgotovi veliku večeru i pozva mnoge. Kad je bilo vrijeme večeri, pošalje svojega slugu da rekne uzvanicima neka dođu, jer je sve spremljeno. Ali se svi redom počnu ispričavati. Prvi mu reče: Kupio sam zaselak, moram poći da ga vidim. Molim te, ispričaj me. Drugi reče: Kupio sam pet jarama volova, idem da ih okušam. Molim te, ispričaj me. Treći reče: Oženio sam se i zato ne mogu doći. Sluga se vrati i javi to svojemu gospodaru. Tada se domaćin rasrdi i naloži svojemu slugi: Idi brzo na trgove i gradske ulice i dovedi ovamo siromahe, sakate, slijepe i hrome. I sluga javi: Gospodaru, učinjeno je kako si zapovjedio, ali još ima mjesta. Gospodar reče slugi: Izađi na putove i među ograde, pa natjeraj ljude da dođu, da mi se napuni kuća. A kažem vam da ni jedan od onih koji su bili pozvani neće okusiti moje večere."},"f6b18c7474825d4d":{"t":"Ps 6, 5\nObazri se, Gospodine, i izbavi moju dušu. Spasi me poradi milosrđa svoga."},"4ab0be99f017fee7":{"t":"Prinos koji ćemo imenu tvojem prikazati, Gospodine, neka nas očisti i neka nas potiče iz dana u dan da provodimo nebeski život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"70cfdfd70237e1bb":{"t":"Ps 12, 6\nPjevat ću Gospodinu koji me je obdario dobrima, klicat ću imenu tvojemu, Svevišnji."},"d488371aeeb90570":{"t":"<i>Pomolimo se</i>.\nPošto smo primili svete darove, molimo, Gospodine, da čestim primanjem otajstva poraste plod našeg spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
